from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.2
.target sm_89
.address_size 64
.visible .entry tanh_kernel(
    .param .u64 in_ptr,
    .param .u64 out_ptr,
    .param .u32 n
)
{
    .reg .u64 %rd<13>;
    .reg .u32 %r<20>;
    .reg .f32 %f<12>;
    .reg .pred %p<8>;
    ld.param.u64 %rd1, [in_ptr];
    ld.param.u64 %rd2, [out_ptr];
    ld.param.u32 %r1, [n];
    cvta.to.global.u64 %rd1, %rd1;
    cvta.to.global.u64 %rd2, %rd2;
    // vec_n = n / 4 (number of full float4 chunks)
    shr.u32 %r2, %r1, 2;
    mov.u32 %r3, %ctaid.x;
    mov.u32 %r4, %ntid.x;
    mov.u32 %r5, %tid.x;
    mad.lo.s32 %r6, %r3, %r4, %r5;
    mov.u32 %r7, %nctaid.x;
    mul.lo.s32 %r8, %r7, %r4;
    // 4x unrolled grid-stride loop: stride = total_threads * 4
    mul.lo.s32 %r14, %r8, 4;
    mov.u32 %r9, %r6;
    // Precompute byte-stride between consecutive unrolled chunks (avoids
    // repeated 32x32->64 multiplies inside the loop; derive chunk1/chunk2/
    // chunk3 byte offsets from chunk0's offset using cheap 64-bit adds).
    mul.wide.s32 %rd9, %r8, 16;
    add.s64 %rd10, %rd9, %rd9;
    add.s64 %rd11, %rd10, %rd9;
vec_loop_start:
    setp.ge.s32 %p1, %r9, %r2;
    @%p1 bra vec_loop_end;
    mul.wide.s32 %rd3, %r9, 16;
    add.s64 %rd4, %rd1, %rd3;
    ld.global.nc.v4.f32 {%f1, %f2, %f3, %f4}, [%rd4];
    tanh.approx.f32 %f5, %f1;
    tanh.approx.f32 %f6, %f2;
    tanh.approx.f32 %f7, %f3;
    tanh.approx.f32 %f8, %f4;
    add.s64 %rd5, %rd2, %rd3;
    st.global.cs.v4.f32 [%rd5], {%f5, %f6, %f7, %f8};
    add.s32 %r10, %r9, %r8;
    setp.ge.s32 %p2, %r10, %r2;
    @%p2 bra skip_chunk1;
    add.s64 %rd12, %rd3, %rd9;
    add.s64 %rd4, %rd1, %rd12;
    ld.global.nc.v4.f32 {%f1, %f2, %f3, %f4}, [%rd4];
    tanh.approx.f32 %f5, %f1;
    tanh.approx.f32 %f6, %f2;
    tanh.approx.f32 %f7, %f3;
    tanh.approx.f32 %f8, %f4;
    add.s64 %rd5, %rd2, %rd12;
    st.global.cs.v4.f32 [%rd5], {%f5, %f6, %f7, %f8};
skip_chunk1:
    add.s32 %r10, %r10, %r8;
    setp.ge.s32 %p3, %r10, %r2;
    @%p3 bra skip_chunk2;
    add.s64 %rd12, %rd3, %rd10;
    add.s64 %rd4, %rd1, %rd12;
    ld.global.nc.v4.f32 {%f1, %f2, %f3, %f4}, [%rd4];
    tanh.approx.f32 %f5, %f1;
    tanh.approx.f32 %f6, %f2;
    tanh.approx.f32 %f7, %f3;
    tanh.approx.f32 %f8, %f4;
    add.s64 %rd5, %rd2, %rd12;
    st.global.cs.v4.f32 [%rd5], {%f5, %f6, %f7, %f8};
skip_chunk2:
    add.s32 %r10, %r10, %r8;
    setp.ge.s32 %p4, %r10, %r2;
    @%p4 bra skip_chunk3;
    add.s64 %rd12, %rd3, %rd11;
    add.s64 %rd4, %rd1, %rd12;
    ld.global.nc.v4.f32 {%f1, %f2, %f3, %f4}, [%rd4];
    tanh.approx.f32 %f5, %f1;
    tanh.approx.f32 %f6, %f2;
    tanh.approx.f32 %f7, %f3;
    tanh.approx.f32 %f8, %f4;
    add.s64 %rd5, %rd2, %rd12;
    st.global.cs.v4.f32 [%rd5], {%f5, %f6, %f7, %f8};
skip_chunk3:
    add.s32 %r9, %r9, %r14;
    bra vec_loop_start;
vec_loop_end:
    // handle remainder elements (0..3) not covered by vectorized loop
    mul.lo.s32 %r11, %r2, 4;
    sub.s32 %r12, %r1, %r11;
    setp.ge.s32 %p5, %r6, %r12;
    @%p5 bra tail_end;
    add.s32 %r13, %r11, %r6;
    mul.wide.s32 %rd6, %r13, 4;
    add.s64 %rd7, %rd1, %rd6;
    ld.global.nc.f32 %f9, [%rd7];
    tanh.approx.f32 %f10, %f9;
    add.s64 %rd8, %rd2, %rd6;
    st.global.cs.f32 [%rd8], %f10;
