        # Cap the grid to a multiple of the SM count so the kernel's built-in
        # grid-stride loop actually performs multiple iterations per thread,
        # reducing block-launch/scheduling overhead and improving L2 reuse
        # for this large, memory-bound elementwise workload.
        sm_count = torch.cuda.get_device_properties(x.device).multi_processor_count
        max_blocks = sm_count * 32
        grid_x = max(1, min(grid_x, max_blocks))

